import {CompatAudio,prepareAudio} from './compat-audio.mjs';
import {parseName,catalog,attachSubtitles,videoFile,subtitleFile,toVtt,key,quality} from './media.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const BASE=new URL('./',import.meta.url).pathname,MEDIA_PATH=BASE+'drive-media/';
const STORE='iamtt-web-v1',FOLDER='application/vnd.google-apps.folder',SHORTCUT='application/vnd.google-apps.shortcut';
const defaults={clientId:'',account:'',folders:[],profiles:[{id:'default',name:'You',color:0}],activeProfile:'default',history:{},files:[],metadata:{},autoplayNext:true};
let stored={};try{stored=JSON.parse(localStorage.getItem(STORE)||'{}')}catch{}
const state={...defaults,...stored};if(!Array.isArray(state.profiles)||!state.profiles.length)state.profiles=defaults.profiles;if(!state.profiles.some(p=>p.id===state.activeProfile))state.activeProfile=state.profiles[0].id;
let token='',expiresAt=0,view='all',search='',scanning=false,scanAbort=null,current=null,playGeneration=0,detailId=null,toastTimer,installPrompt,folderStack=[],folderMode='root',browseGeneration=0,metadataBusy=false;
let compatAudio=null;
const localFiles=new Map(),mediaUrls=new Set();const colors=['#d0d3d9','#bfc9de','#cabfd6','#b9cdc7','#d8c4b7','#c7caaf'];
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state))}catch{toast('Browser storage is full. Recent progress could not be saved.')}}
function profile(){return state.profiles.find(p=>p.id===state.activeProfile)||state.profiles[0]}
function history(){const scope=(state.account||'local')+':'+state.activeProfile;return state.history[scope]||(state.history[scope]={})}
function titles(){return catalog(state.files)}
function metadata(t){return state.metadata[t.id]||{}}
function safeUrl(s){try{const u=new URL(s);return u.protocol==='https:'?u.href:''}catch{return ''}}
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,6000)}
function fail(error){toast(error?.message||'Something went wrong. Please try again.')}
function run(action){return async(...args)=>{try{await action(...args)}catch(e){fail(e)}}}
function open(id){const d=$(id);if(!d.open)d.showModal()}
function settings(){renderSettings();open('settings-dialog')}
function connected(){return token&&expiresAt>Date.now()+10000}
function requireDrive(){if(!connected())throw new Error('Connect Google Drive in Settings to continue.')}
function button(label,action,classes='button secondary'){const b=document.createElement('button');b.className=classes;b.textContent=label;b.addEventListener('click',run(action));return b}
function progress(file){return history()[file.id]||{position:0,duration:0}}
function nextFile(title){const h=history();if(title.type==='movie')return title.files[0];const resume=title.files.filter(f=>h[f.id]?.position>5&&!h[f.id]?.completed).sort((a,b)=>(h[b.id]?.updated||0)-(h[a.id]?.updated||0))[0];return resume||title.files.find(f=>!h[f.id]?.completed)||title.files[0]}
function labelFile(file){const p=file.parsed||parseName(file.name,file.path);return p.type==='show'?`S${String(p.season).padStart(2,'0')} · E${String(p.episode).padStart(2,'0')}${p.episodeTitle?' · '+p.episodeTitle:''}`:file.name}
function posterMarkup(t){const m=metadata(t),image=safeUrl(m.poster);return image?`<img src="${esc(image)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<div class="poster-fallback">${esc(t.title)}<span>${t.type==='show'?'TV SERIES':'MOVIE'}</span></div>`}
function makeCard(t,continueWatching=false){const f=nextFile(t),h=progress(f),m=metadata(t);const b=document.createElement('button');b.className='poster-card';b.dataset.titleId=t.id;b.setAttribute('aria-label',(continueWatching?'Resume ':'Open ')+t.title);b.innerHTML=`<div class="poster">${posterMarkup(t)}${t.type==='show'?'<span class="poster-badge">SERIES</span>':''}${continueWatching&&h.duration?`<span class="poster-progress" style="width:${Math.min(100,100*h.position/h.duration)}%"></span>`:''}</div><span class="poster-name">${esc(t.title)}</span><span class="poster-meta">${esc(continueWatching&&t.type==='show'?labelFile(f):[t.year||m.year,t.type==='show'?t.files.length+' episode'+(t.files.length===1?'':'s'):m.genres?.[0]||'Movie'].filter(Boolean).join(' · '))}</span>`;b.addEventListener('click',()=>showDetail(t.id));b.querySelector('img')?.addEventListener('error',e=>{e.target.parentElement.innerHTML=`<div class="poster-fallback">${esc(t.title)}<span>${t.type==='show'?'TV SERIES':'MOVIE'}</span></div>`});return b}
function section(name,items,continueWatching=false){if(!items.length)return;const s=document.createElement('section');s.className='library-section';s.innerHTML=`<div class="section-line"><h2>${esc(name)}</h2><span class="section-count">${items.length} title${items.length===1?'':'s'}</span></div><div class="poster-grid"></div>`;for(const t of items)s.lastElementChild.append(makeCard(t,continueWatching));$('library-content').append(s)}
function renderBanner(){const banner=$('connection-banner');banner.replaceChildren();if(scanning){banner.hidden=false;const p=document.createElement('span');p.innerHTML='<span class="spinner"></span><span id="scan-progress">Scanning your folders…</span>';banner.append(p,button('Cancel',()=>scanAbort?.abort(),'button secondary small-button'));return}const drive=state.files.some(f=>f.source==='drive');if((state.folders.length||drive)&&!connected()){banner.hidden=false;const p=document.createElement('span');p.textContent='Reconnect Google Drive to refresh your library or play a Drive video.';banner.append(p,button('Reconnect',connect,'button secondary small-button'))}else banner.hidden=true}
function render(){const p=profile();$('profile-button').textContent=p.name.slice(0,1).toUpperCase();$('profile-button').style.background=colors[p.color%colors.length];$('profile-button').setAttribute('aria-label','Switch profile. Current profile: '+p.name);$('greeting').textContent=p.name==='You'?'YOUR COLLECTION':p.name.toUpperCase()+'’S COLLECTION';$('page-title').textContent=view==='movie'?'Your movies.':view==='show'?'Your shows.':'Your library.';
 const all=titles(),visible=all.filter(t=>(view==='all'||t.type===view)&&(!search||[t.title,t.year,...(metadata(t).genres||[])].join(' ').toLowerCase().includes(search.toLowerCase())));$('library-status').textContent=all.length?`${all.length} title${all.length===1?'':'s'} · ${state.files.length} video${state.files.length===1?'':'s'}`:'Movies and shows from the folders you choose.';$('empty-state').hidden=all.length>0;$('library-content').replaceChildren();renderBanner();$('refresh-button').disabled=scanning||!connected()||!state.folders.length;
 if(!all.length)return;if(!visible.length){const p=document.createElement('p');p.className='no-results';p.textContent=search?'No titles match your search.':'No '+(view==='show'?'TV shows':'movies')+' in your selected folders yet.';$('library-content').append(p);return}
 if(search||view!=='all'){section(search?'Search results':view==='movie'?'Movies':'TV Shows',visible);return}
 const h=history();const continued=visible.filter(t=>t.files.some(f=>h[f.id]?.position>5&&!h[f.id]?.completed)).sort((a,b)=>Math.max(...b.files.map(f=>h[f.id]?.updated||0))-Math.max(...a.files.map(f=>h[f.id]?.updated||0)));section('Continue watching',continued,true);section('Recently added',[...visible].sort((a,b)=>b.modifiedTime.localeCompare(a.modifiedTime)).slice(0,8));section('Movies',visible.filter(t=>t.type==='movie'));section('TV Shows',visible.filter(t=>t.type==='show'));}
function renderSettings(){$('origin').textContent=location.origin;$('client-id').value=state.clientId;$('account-status').textContent=connected()?'Connected as '+state.account:state.account?'Reconnect '+state.account:'Not connected';$('google-connect').textContent=connected()?'Switch Google account':'Connect Google Drive';$('google-disconnect').hidden=!state.account;$('browse-folders').disabled=!connected();$('autoplay-next').checked=state.autoplayNext;$('saved-folders').replaceChildren();if(!state.folders.length){const p=document.createElement('p');p.className='muted small';p.textContent='No folders selected yet.';$('saved-folders').append(p)}for(const folder of state.folders){const row=document.createElement('div');row.className='saved-folder';row.innerHTML=`<div>${esc(folder.name)}<small>${esc(folder.id)}</small></div>`;const b=button('✕',()=>{if(scanning)throw new Error('Finish or cancel the scan before removing a folder.');state.folders=state.folders.filter(f=>f.id!==folder.id);state.files=state.files.filter(f=>f.sourceFolder!==folder.id);persist();syncWorker();renderSettings();render()},'icon-button');b.setAttribute('aria-label','Remove folder '+folder.name+' from IAMTT');row.append(b);$('saved-folders').append(row)}if(!state.clientId)$('oauth-setup').open=true}
async function googleReady(){if(window.google?.accounts?.oauth2)return;await new Promise((resolve,reject)=>{const start=Date.now(),timer=setInterval(()=>{if(window.google?.accounts?.oauth2){clearInterval(timer);resolve()}else if(Date.now()-start>12000){clearInterval(timer);reject(new Error('Google sign-in could not load. Check your internet connection and browser content blockers.'))}},100)})}
async function connect(){if(!state.clientId){settings();$('oauth-setup').open=true;$('client-id').focus();toast('Add a Web OAuth client ID once to connect Google Drive.');return}await googleReady();await new Promise((resolve,reject)=>{const client=google.accounts.oauth2.initTokenClient({client_id:state.clientId,scope:'https://www.googleapis.com/auth/drive.readonly',include_granted_scopes:false,callback:async response=>{try{if(response.error)throw new Error(response.error_description||response.error);if(!google.accounts.oauth2.hasGrantedAllScopes(response,'https://www.googleapis.com/auth/drive.readonly'))throw new Error('Allow read-only Drive access to open your video folders.');token=response.access_token;expiresAt=Date.now()+Number(response.expires_in)*1000;const about=await drive('about',{fields:'user(displayName,emailAddress)'});const account=about.user.emailAddress;if(state.account&&state.account!==account){scanAbort?.abort();state.folders=[];state.files=state.files.filter(f=>f.source!=='drive');await syncWorker()}state.account=account;persist();await syncWorker();renderSettings();render();if($('player-dialog').open&&current?.file.source==='drive'){const v=$('video'),position=v.currentTime||progress(current.file).position;v.src=MEDIA_PATH+encodeURIComponent(current.file.id)+'?reconnect='+Date.now();v.addEventListener('loadedmetadata',()=>{v.currentTime=position;v.play().catch(()=>{})},{once:true})}toast('Google Drive connected. Choose your library folders.');resolve()}catch(e){token='';expiresAt=0;await syncWorker();render();reject(e)}},error_callback:e=>reject(new Error(e.type==='popup_closed'?'Google sign-in was closed.':'Google sign-in could not open. Allow popups and try again.'))});client.requestAccessToken({prompt:'select_account'})})}
async function disconnect(){scanAbort?.abort();closePlayer();token='';expiresAt=0;state.account='';state.folders=[];state.files=state.files.filter(f=>f.source!=='drive');persist();await syncWorker();renderSettings();render();toast('Google Drive disconnected from this browser.');}
async function drive(path,params={},signal){requireDrive();const url=new URL('https://www.googleapis.com/drive/v3/'+path);for(const [k,v]of Object.entries(params))url.searchParams.set(k,v);const r=await fetch(url,{headers:{Authorization:'Bearer '+token},signal,cache:'no-store',credentials:'omit'});if(!r.ok){let msg='';try{msg=(await r.json()).error?.message||''}catch{}if(r.status===401){token='';expiresAt=0;syncWorker();render();throw new Error('Google sign-in expired. Reconnect Google Drive in Settings.')}if(r.status===403&&/not been used|disabled|accessNotConfigured/i.test(msg))throw new Error('Enable Google Drive API in your Google Cloud project first.');if(r.status===404)throw new Error('Folder not found. Check the link and the connected Google account.');throw new Error('Google Drive refused access ('+r.status+'). '+msg)}return params.alt==='media'?r:r.json()}
async function listFiles(q,signal){let next='',files=[];do{const page=await drive('files',{q,fields:'nextPageToken,files(id,name,mimeType,size,modifiedTime,videoMediaMetadata(durationMillis,width,height),shortcutDetails(targetId,targetMimeType))',pageSize:1000,orderBy:'name',supportsAllDrives:true,includeItemsFromAllDrives:true,...(next?{pageToken:next}:{})},signal);files.push(...(page.files||[]));next=page.nextPageToken||''}while(next);return files}
function folderId(value){value=value.trim();let id=value;if(value.includes('://')){let url;try{url=new URL(value)}catch{throw new Error('Paste a Google Drive folder link or folder ID.')}if(url.hostname!=='drive.google.com')throw new Error('Use a folder link from drive.google.com.');id=/\/folders\/([a-zA-Z0-9_-]+)/.exec(url.pathname)?.[1]||url.searchParams.get('id')||''}if(!/^[a-zA-Z0-9_-]{8,}$/.test(id))throw new Error('That is not a Google Drive folder ID.');return id}
async function addFolder(id){requireDrive();if(scanning)throw new Error('Finish or cancel the current scan before adding another folder.');const f=await drive('files/'+encodeURIComponent(id),{fields:'id,name,mimeType',supportsAllDrives:true});if(f.mimeType!==FOLDER)throw new Error('Choose a folder, rather than a video file.');if(state.folders.some(x=>x.id===id)){toast('That folder is already in your library.');return}state.folders.push({id:f.id,name:f.name});persist();renderSettings();await scanDrive()}
async function scanDrive(){requireDrive();if(scanning)return;if(!state.folders.length){settings();toast('Add a Drive folder first.');return}scanning=true;scanAbort=new AbortController();const signal=scanAbort.signal,account=state.account,roots=state.folders.map(f=>({...f})),videos=[],subs=[],visited=new Set();render();try{
 async function walk(id,path,root,depth){if(depth>12)throw new Error('A folder is nested more than 12 levels deep. Add that folder directly.');const visitKey=root+':'+id;if(visited.has(visitKey))return;visited.add(visitKey);if(visited.size>2000)throw new Error('This scan contains more than 2,000 folders. Choose smaller library folders.');const files=await listFiles(`'${id}' in parents and trashed = false`,signal);for(const f of files){if(signal.aborted)throw new DOMException('Aborted','AbortError');if(f.mimeType===FOLDER)await walk(f.id,path?path+'/'+f.name:f.name,root,depth+1);else if(f.mimeType===SHORTCUT&&f.shortcutDetails?.targetMimeType===FOLDER)await walk(f.shortcutDetails.targetId,path?path+'/'+f.name:f.name,root,depth+1);else if(videoFile(f.name,f.mimeType)||subtitleFile(f.name)){const item={id:f.id,name:f.name,path,size:Number(f.size)||0,mimeType:f.mimeType,modifiedTime:f.modifiedTime||'',duration:Number(f.videoMediaMetadata?.durationMillis||0)/1000,height:Number(f.videoMediaMetadata?.height||0),source:'drive',sourceFolder:root};(subtitleFile(f.name)?subs:videos).push(item)}if($('scan-progress'))$('scan-progress').textContent=`Scanning ${videos.length} video${videos.length===1?'':'s'}…`}}
 for(const root of roots)await walk(root.id,'',root.id,0);if(signal.aborted||account!==state.account)throw new DOMException('Aborted','AbortError');const seen=new Set();const result=attachSubtitles(videos,subs).filter(f=>{if(seen.has(f.id))return false;seen.add(f.id);return true});state.files=[...state.files.filter(f=>f.source!=='drive'),...result];persist();await syncWorker();toast(`Library refreshed · ${result.length} Drive video${result.length===1?'':'s'}`)}catch(e){if(e.name==='AbortError')toast('Scan cancelled. Your existing library was kept.');else throw e}finally{scanning=false;scanAbort=null;render();enrich()}}
async function browse(mode='root',folder=null){requireDrive();folderMode=mode;if(folder)folderStack.push(folder);else folderStack=[];open('folders-dialog');await renderFolderBrowser()}
async function renderFolderBrowser(){const generation=++browseGeneration,container=$('folder-browser');container.textContent='Loading folders…';const currentFolder=folderStack.at(-1);$('folder-breadcrumb').replaceChildren(button(folderMode==='shared'?'Shared with me':'My Drive',()=>{folderStack=[];return renderFolderBrowser()},''));folderStack.forEach((f,i)=>{$('folder-breadcrumb').append(document.createTextNode(' / '),button(f.name,()=>{folderStack=folderStack.slice(0,i+1);return renderFolderBrowser()},''))});$('add-current-folder').hidden=!currentFolder;$('add-current-folder').onclick=currentFolder?run(()=>addFolder(currentFolder.id)):null;const q=currentFolder?`'${currentFolder.id}' in parents and trashed = false and (mimeType = '${FOLDER}' or mimeType = '${SHORTCUT}')`:folderMode==='shared'?`sharedWithMe = true and trashed = false and mimeType = '${FOLDER}'`:`'root' in parents and trashed = false and (mimeType = '${FOLDER}' or mimeType = '${SHORTCUT}')`;try{const files=await listFiles(q);if(generation!==browseGeneration)return;container.replaceChildren();const folders=files.map(f=>f.mimeType===SHORTCUT&&f.shortcutDetails?.targetMimeType===FOLDER?{...f,id:f.shortcutDetails.targetId,mimeType:FOLDER}:f).filter(f=>f.mimeType===FOLDER);if(!folders.length)container.textContent='No subfolders here.';for(const f of folders){const row=document.createElement('div');row.className='folder-row';row.innerHTML='<span class="folder-icon" aria-hidden="true">▱</span>';row.append(button(f.name,()=>{folderStack.push({id:f.id,name:f.name});return renderFolderBrowser()},'folder-open'),button(state.folders.some(x=>x.id===f.id)?'Added':'Add',()=>addFolder(f.id),'button secondary small-button'));container.append(row)}}catch(e){if(generation===browseGeneration)container.textContent=e.message}}
async function openLocal(files){const added=[],subs=[];for(const f of files){if(!videoFile(f.name,f.type)&&!subtitleFile(f.name))continue;const relative=f.webkitRelativePath||f.name,path=relative.includes('/')?relative.slice(0,relative.lastIndexOf('/')):'';const id='local:'+relative+':'+f.size+':'+f.lastModified;localFiles.set(id,f);const item={id,name:f.name,path,size:f.size,mimeType:f.type,modifiedTime:new Date(f.lastModified).toISOString(),source:'local',sourceFolder:'local'};(subtitleFile(f.name)?subs:added).push(item)}if(!added.length)throw new Error('No video files were selected. Choose MP4, WebM or another supported video.');const result=attachSubtitles(added,subs),ids=new Set(result.map(f=>f.id));state.files=[...state.files.filter(f=>!ids.has(f.id)),...result];persist();render();enrich();$('settings-dialog').close();toast(`${added.length} local video${added.length===1?'':'s'} added. They stay on this device.`)}
async function timedJson(url){const response=await fetch(url,{signal:AbortSignal.timeout(10000),credentials:'omit'});if(!response.ok)throw new Error('Metadata unavailable');return response.json()}
async function enrich(){
  if(metadataBusy)return;
  metadataBusy=true;
  try {
    for(const t of titles()) {
      const cached=metadata(t);
      if(cached.checkedAt && Date.now()-cached.checkedAt<7*86400000)continue;
      let data={checkedAt:Date.now()};
      try {
        if(t.type==='show') {
          const show=await timedJson('https://api.tvmaze.com/singlesearch/shows?q='+encodeURIComponent(t.title)+'&embed=episodes');
          if(key(show.name)===key(t.title)||key(show.name).startsWith(key(t.title))) {
            data={...data,poster:show.image?.original||show.image?.medium||'',summary:new DOMParser().parseFromString(show.summary||'','text/html').body.textContent,genres:show.genres||[],year:Number(show.premiered?.slice(0,4))||null,episodes:Object.fromEntries((show._embedded?.episodes||[]).map(e=>[e.season+':'+e.number,{name:e.name,runtime:e.runtime}]))};
          }
        } else {
          const query=t.title+(t.year?' '+t.year:'')+' film';
          const url='https://en.wikipedia.org/w/api.php?origin=*&action=query&format=json&generator=search&gsrnamespace=0&gsrlimit=5&gsrsearch='+encodeURIComponent(query)+'&prop=pageimages|extracts&piprop=thumbnail&pilicense=any&pithumbsize=600&exintro=1&explaintext=1&exsentences=3';
          const result=await timedJson(url);
          const pages=Object.values(result.query?.pages||{});
          const page=pages.find(p=>key(p.title.replace(/\s*\([^)]*\)$/, ''))===key(t.title)&&/\bfilm\b/i.test(p.extract||'')&&(!t.year||(p.extract||'').includes(String(t.year))||p.title.includes(String(t.year))));
          if(page)data={...data,poster:page.thumbnail?.source||'',summary:page.extract?.split('\n')[0]||'',year:t.year,genres:[]};
        }
      } catch {}
      state.metadata[t.id]=data;
      persist();render();
      if($('detail-dialog').open&&detailId===t.id)showDetail(t.id);
      await new Promise(r=>setTimeout(r,1200));
    }
  } finally {metadataBusy=false;}
}
function showDetail(id){const t=titles().find(t=>t.id===id);if(!t)return;detailId=id;const m=metadata(t),f=nextFile(t),h=progress(f);$('title-detail').innerHTML=`<div class="detail-top"><div class="detail-poster">${posterMarkup(t)}</div><div class="detail-info"><p class="eyebrow">${t.type==='show'?'TV SERIES':'MOVIE'}</p><h2>${esc(t.title)}</h2><div class="detail-metadata"><span>${esc(t.year||m.year||'')}</span><span>${esc(t.type==='show'?t.files.length+' episodes':quality(f)?quality(f)+'p':'')}</span><span>${esc((m.genres||[]).join(' · '))}</span></div><p class="description">${esc(m.summary||'From your selected library folders.')}</p><div id="detail-actions" class="button-row"></div><p class="small muted">${esc(t.type==='show'?labelFile(f):f.name)}</p></div></div><div id="episodes" class="episode-list"></div>`;$('detail-actions').append(button(h.position>5&&!h.completed?'Resume':'Play',()=>play(t,f),'button primary'));if(h.position>5)$('detail-actions').append(button('Start over',()=>play(t,f,true)));if(t.type==='show'){let season=-1;for(const file of t.files){if(file.parsed.season!==season){season=file.parsed.season;const heading=document.createElement('h3');heading.className='season-label';heading.textContent='Season '+season;$('episodes').append(heading)}const epMeta=m.episodes?.[season+':'+file.parsed.episode],ph=progress(file);const row=document.createElement('button');row.className='episode-row';row.innerHTML=`<span class="episode-number">${file.parsed.episode}</span><div>${esc(epMeta?.name||file.parsed.episodeTitle||'Episode '+file.parsed.episode)}<small>${esc(file.name)}</small></div><span class="episode-state">${ph.completed?'Watched':ph.position>5?'Resume':'Play'}</span>`;row.addEventListener('click',run(()=>play(t,file)));$('episodes').append(row)}}else{$('episodes').innerHTML=`<p class="small muted">${esc((Number(f.size)/1024**3).toFixed(2))} GB · ${esc(f.source==='drive'?'Google Drive':'This device')}</p>`}open('detail-dialog')}
async function serviceReady(){if(!('serviceWorker'in navigator))throw new Error('This browser cannot stream private Drive files. Use a current Chrome, Edge, Firefox or Safari browser.');await navigator.serviceWorker.register(new URL('./sw.js',import.meta.url),{scope:BASE});await navigator.serviceWorker.ready;if(!navigator.serviceWorker.controller){await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(new Error('Refresh IAMTT once to enable Drive playback.')),10000);navigator.serviceWorker.addEventListener('controllerchange',()=>{clearTimeout(timeout);resolve()},{once:true})})}}
async function syncWorker(){const worker=navigator.serviceWorker?.controller;if(!worker)return;const files=state.files.filter(f=>f.source==='drive').flatMap(f=>[f,...(f.subtitles||[])]).map(f=>({id:f.id,size:f.size||0,mimeType:f.mimeType||'video/mp4'}));await new Promise(resolve=>{const channel=new MessageChannel(),timer=setTimeout(resolve,2000);channel.port1.onmessage=()=>{clearTimeout(timer);channel.port1.close();resolve()};worker.postMessage(token?{type:'AUTH',token,expiresAt,files}:{type:'CLEAR_AUTH'},[channel.port2])})}
function objectUrl(blob){const url=URL.createObjectURL(blob);mediaUrls.add(url);return url}
function saveProgress(){if(!current)return;const v=$('video');if(!Number.isFinite(v.currentTime)||!Number.isFinite(v.duration)||v.duration<=0)return;history()[current.file.id]={position:v.currentTime,duration:v.duration,updated:Date.now(),completed:v.ended||(v.duration>60&&v.currentTime>=v.duration-30)};persist()}
function releaseUrls(){for(const url of mediaUrls)URL.revokeObjectURL(url);mediaUrls.clear()}
async function play(title,file,startOver=false){prepareAudio($('video'),/\.mkv$/i.test(file.name));if(file.source==='drive'){requireDrive();await serviceReady();await syncWorker()}else if(!localFiles.has(file.id)){settings();throw new Error('Reselect this local video or its folder. Browsers cannot reopen local files automatically.')}
 saveProgress();compatAudio?.dispose();compatAudio=null;++playGeneration;const generation=playGeneration;const v=$('video');v.pause();v.removeAttribute('src');v.load();releaseUrls();current={title,file};$('detail-dialog').close();$('video').replaceChildren();$('subtitle-select').innerHTML='<option value="">Off</option>';$('player-title').textContent=title.title;$('player-subtitle').textContent=title.type==='show'?labelFile(file):'';$('player-message').textContent='';const idx=title.files.findIndex(f=>f.id===file.id);$('next-episode').hidden=title.type!=='show'||idx>=title.files.length-1;
 const saved=startOver?0:progress(file).position;v.addEventListener('loadedmetadata',()=>{if(generation!==playGeneration)return;if(saved>5&&Number.isFinite(v.duration))v.currentTime=Math.min(saved,Math.max(0,v.duration-1));v.play().catch(()=>{$('player-message').textContent='Press Play to start the video.'})},{once:true});v.src=file.source==='drive'?MEDIA_PATH+encodeURIComponent(file.id):objectUrl(localFiles.get(file.id));open('player-dialog');v.load();v.play().catch(()=>{});
 $('restore-audio').hidden=true;
 if(/\.mkv$/i.test(file.name)){
  $('player-message').textContent='Checking audio…';
  const audio=new CompatAudio(v,{url:v.src,blob:file.source==='local'?localFiles.get(file.id):undefined,size:file.size,onStatus:(message,error=false)=>{if(generation!==playGeneration)return;$('player-message').textContent=message;$('restore-audio').hidden=!error&&!audio.active}});
  compatAudio=audio;audio.init().then(active=>{if(generation!==playGeneration)return;if(active)$('restore-audio').hidden=false;else if(!audio.active&&$('player-message').textContent==='Checking audio…')$('player-message').textContent='';});
 }else if(/\.(avi|ts|m2ts)$/i.test(file.name))$('player-message').textContent='Playback support depends on your browser.';
 for(const sub of file.subtitles||[]){try{const content=sub.source==='drive'?await (await drive('files/'+encodeURIComponent(sub.id),{alt:'media',supportsAllDrives:true})).text():await localFiles.get(sub.id)?.text();if(generation!==playGeneration)return;if(content)addTrack(content,sub.name)}catch{if(generation===playGeneration)$('player-message').textContent='Video ready. A sidecar subtitle could not be loaded; you can load a subtitle manually.'}}
}
function addTrack(text,name){const track=document.createElement('track');track.kind='subtitles';track.label=name;const language=/[ ._\-](en|ms|zh|ta|hi|id)(?:[ ._\-]|\.(?:srt|vtt|ass|ssa)$)/i.exec(name)?.[1]||'en';track.srclang=language;track.src=objectUrl(new Blob([toVtt(text,name)],{type:'text/vtt'}));$('video').append(track);const option=document.createElement('option');option.value=String($('video').textTracks.length-1);option.textContent=name;$('subtitle-select').append(option);if($('subtitle-select').options.length===2){track.default=true;$('subtitle-select').value=option.value;track.addEventListener('load',()=>track.track.mode='showing',{once:true})}}
function closePlayer(){saveProgress();compatAudio?.dispose();compatAudio=null;++playGeneration;const v=$('video');v.pause();v.removeAttribute('src');v.replaceChildren();v.load();current=null;releaseUrls();if($('player-dialog').open)$('player-dialog').close();render()}
async function nextEpisode(){if(!current)return;const {title,file}=current;const i=title.files.findIndex(f=>f.id===file.id);if(title.type==='show'&&title.files[i+1])await play(title,title.files[i+1])}
function renderProfiles(){$('profiles-list').replaceChildren();for(const p of state.profiles){const tile=document.createElement('div');tile.className='profile-tile';const b=document.createElement('button');b.className='profile-choice'+(p.id===state.activeProfile?' active':'');b.innerHTML=`<span class="avatar" style="background:${colors[p.color%colors.length]}">${esc(p.name.slice(0,1).toUpperCase())}</span><span>${esc(p.name)}</span>`;b.addEventListener('click',()=>{saveProgress();state.activeProfile=p.id;persist();$('profiles-dialog').close();render()});tile.append(b,button('Edit',()=>{const name=prompt('Profile name',p.name);if(name===null)return;if(name.trim()){p.name=name.trim().slice(0,24);persist();renderProfiles();render()}else if(state.profiles.length>1&&confirm('Remove this profile and its viewing progress?')){state.profiles=state.profiles.filter(x=>x.id!==p.id);for(const scope of Object.keys(state.history))if(scope.endsWith(':'+p.id))delete state.history[scope];if(state.activeProfile===p.id)state.activeProfile=state.profiles[0].id;persist();renderProfiles();render()}},'profile-edit'));$('profiles-list').append(tile)}}
function bind(){$('restore-audio').onclick=run(()=>compatAudio?.restore());$('settings-button').onclick=settings;$('connect-empty').onclick=run(connect);$('local-empty').onclick=()=>$('local-files-input').click();$('google-connect').onclick=run(connect);$('google-disconnect').onclick=run(disconnect);$('refresh-button').onclick=run(scanDrive);$('profile-button').onclick=()=>{renderProfiles();open('profiles-dialog')};$('save-client').onclick=()=>{const id=$('client-id').value.trim();if(!/^[a-zA-Z0-9_-]+\.apps\.googleusercontent\.com$/.test(id)){toast('Paste a valid Web OAuth client ID ending in .apps.googleusercontent.com.');return}if(id!==state.clientId&&token){token='';expiresAt=0;syncWorker()}state.clientId=id;persist();render();renderSettings();toast('Web client ID saved. You can connect Google Drive now.')};$('copy-origin').onclick=run(async()=>{await navigator.clipboard.writeText(location.origin);toast('Address copied.')});$('browse-folders').onclick=run(()=>browse());$('my-drive').onclick=run(()=>browse('root'));$('shared-drive').onclick=run(()=>browse('shared'));$('folder-form').onsubmit=run(async e=>{e.preventDefault();await addFolder(folderId($('folder-link').value));$('folder-link').value=''});$('profile-form').onsubmit=e=>{e.preventDefault();const name=$('profile-name').value.trim();if(!name)return;state.profiles.push({id:crypto.randomUUID(),name:name.slice(0,24),color:state.profiles.length%colors.length});persist();$('profile-name').value='';renderProfiles()};$('local-folder-button').onclick=()=>$('local-folder-input').click();$('local-files-button').onclick=()=>$('local-files-input').click();for(const id of ['local-folder-input','local-files-input'])$(id).onchange=run(async()=>{await openLocal([...$(id).files]);$(id).value=''});$('autoplay-next').onchange=()=>{state.autoplayNext=$('autoplay-next').checked;persist()};$('search').oninput=e=>{search=e.target.value;render()};for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));render()};for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){if(d.id==='player-dialog')closePlayer();else d.close()}});$('close-player').onclick=closePlayer;$('player-dialog').addEventListener('cancel',e=>{e.preventDefault();closePlayer()});$('fullscreen-button').onclick=run(async()=>{const v=$('video');if(document.fullscreenElement)await document.exitFullscreen();else if(v.requestFullscreen)await v.requestFullscreen();else if(v.webkitEnterFullscreen)v.webkitEnterFullscreen();else throw new Error('Full screen is not available in this browser.')});$('next-episode').onclick=run(nextEpisode);$('video').addEventListener('error',()=>{if(current)$('player-message').textContent='This video could not play. Check your Drive connection, or try an MP4 with H.264 video and AAC audio. Browser playback cannot convert unsupported codecs.'});let lastSave=0;$('video').addEventListener('timeupdate',()=>{if(Date.now()-lastSave>5000){saveProgress();lastSave=Date.now()}});$('video').addEventListener('pause',saveProgress);$('video').addEventListener('ended',run(async()=>{saveProgress();if(state.autoplayNext)await nextEpisode();else render()}));$('subtitle-select').onchange=()=>{const choice=$('subtitle-select').value;[...$('video').textTracks].forEach((t,i)=>t.mode=choice===String(i)?'showing':'disabled')};$('load-subtitle').onclick=()=>$('subtitle-input').click();$('subtitle-input').onchange=run(async()=>{const f=$('subtitle-input').files[0];if(f&&current)addTrack(await f.text(),f.name);$('subtitle-input').value=''});window.addEventListener('pagehide',saveProgress);document.addEventListener('visibilitychange',()=>{if(document.hidden)saveProgress()});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install-button').hidden=false});$('install-button').onclick=run(async()=>{if(!installPrompt)return;await installPrompt.prompt();installPrompt=null;$('install-button').hidden=true});window.addEventListener('appinstalled',()=>$('install-button').hidden=true);navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='TOKEN_NEEDED')syncWorker();if(e.data?.type==='STREAM_ERROR'){if(e.data.status===401){token='';expiresAt=0;render()}$('player-message').textContent=e.data.status===401?'Google sign-in expired. Reconnect Drive in Settings, then resume.':'Google Drive refused playback ('+e.data.status+'). Check that you can open this video in Drive.'}});navigator.serviceWorker?.addEventListener('controllerchange',()=>syncWorker());document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||e.target.closest('video'))return;if($('player-dialog').open){const v=$('video');if(e.code==='Space'){e.preventDefault();v.paused?v.play().catch(fail):v.pause()}if(e.key==='ArrowRight'){e.preventDefault();v.currentTime=Math.min(v.duration||Infinity,v.currentTime+10)}if(e.key==='ArrowLeft'){e.preventDefault();v.currentTime=Math.max(0,v.currentTime-10)}}else if(e.target.matches('.poster-card')&&['ArrowRight','ArrowLeft'].includes(e.key)){const cards=[...document.querySelectorAll('.poster-card')],i=cards.indexOf(e.target);cards[i+(e.key==='ArrowRight'?1:-1)]?.focus();e.preventDefault()}})}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'search_iamtt_library',description:'Search movies and shows already in the current IAMTT browser library. Does not connect Google Drive or fetch new files.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200)throw new Error('A query of up to 200 characters is required.');return titles().filter(t=>t.title.toLowerCase().includes(input.query.toLowerCase())).map(t=>({id:t.id,title:t.title,type:t.type,year:t.year,videoCount:t.files.length}))}},{name:'open_iamtt_title_details',description:'Open details for an existing IAMTT library title. Does not start playback.',inputSchema:{type:'object',properties:{titleId:{type:'string'}},required:['titleId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.titleId!=='string'||!titles().some(t=>t.id===input.titleId))throw new Error('Choose an existing library title ID.');showDetail(input.titleId);return {opened:true,titleId:input.titleId}}}];for(const tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
bind();render();renderSettings();registerTools();if('serviceWorker'in navigator)serviceReady().then(syncWorker).catch(()=>{});enrich();

